abstract class Animal {
  public abstract String som();
}
class Gato extends Animal {
  @Override
  public String som() {
    return "Miau";
  }
}
public class Main {
  public static void main(String[] args) {
    Gato animal = new Gato();
    System.out.println(animal.som());
  }
}

class Contador {
  int valor;
  static int criados = 0;
  Contador(int valor) {
    this.valor = valor;
    criados++;
  }
  Contador() {
    this(5);
    valor++;
  }
  public static void main(String[] args) {
    Contador c1 = new Contador();
    Contador c2 = new Contador(c1.valor);
    c1.valor += criados;
    System.out.println(c1.valor + " " + c2.valor + " " + criados);
  }
}

