class Caixa {
  int valor;
  Caixa(int valor) {
    this.valor = valor;
  }
  static void alterar(Caixa a, Caixa b) {
    a.valor = a.valor + 2;
    a = b;
    a.valor = a.valor + 3;
  }
  public static void main(String[] args) {
    Caixa x = new Caixa(5);
    Caixa y = new Caixa(10);
    alterar(x, y);
    System.out.println(x.valor + " " + y.valor);
  }
}

class InTheLoop {
  public static void main(String[] args) {
    int end = Integer.MAX_VALUE;
    int start = end - 100;
    int count = 0;
    for (int i = start; i <= end; i++)
      count++;
    System.out.println(count);
  }
}
